namespace BloodBankLIS.Domain.Rules;

public enum FacilityPolicyValueKind
{
    Integer = 0,
    Boolean = 1
}

public sealed record FacilityPolicyDefinition(
    string Key,
    string Category,
    string DisplayName,
    string Description,
    FacilityPolicyValueKind Kind,
    string DefaultValue,
    string Citation,
    int? MinInclusive = null,
    int? MaxInclusive = null);

